<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: #ffffff;
      --text: #172033;
      --muted: #6b7280;
      --line: #e3e8f0;
      --blue: #4f46e5;
      --blue-dark: #3730a3;
      --shadow: 0 10px 30px rgba(25, 39, 67, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 48px 0 56px;
    }

    .topbar {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 32px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--blue);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.25rem);
      letter-spacing: -0.05em;
      line-height: 1;
    }

    .composer {
      display: flex;
      width: min(100%, 420px);
      gap: 10px;
    }

    #new-card {
      min-width: 0;
      flex: 1;
      border: 1px solid var(--line);
      border-radius: 12px;
      background: var(--panel);
      color: var(--text);
      font: inherit;
      outline: none;
      padding: 13px 15px;
      box-shadow: 0 4px 12px rgba(25, 39, 67, 0.04);
    }

    #new-card:focus {
      border-color: var(--blue);
      box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12);
    }

    #add-card {
      border: 0;
      border-radius: 12px;
      padding: 0 18px;
      background: var(--blue);
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 750;
      transition: background 0.2s ease, transform 0.2s ease;
    }

    #add-card:hover {
      background: var(--blue-dark);
      transform: translateY(-1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
      align-items: start;
    }

    .column {
      min-height: 430px;
      border: 1px solid var(--line);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.72);
      padding: 16px;
      box-shadow: var(--shadow);
      transition: border-color 0.2s ease, background 0.2s ease;
    }

    .column.drag-over {
      border-color: var(--blue);
      background: #f4f3ff;
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 16px;
      padding: 2px 3px;
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      place-items: center;
      border-radius: 999px;
      background: #eef1f7;
      color: var(--muted);
      font-size: 0.8rem;
      font-weight: 800;
    }

    .card-list {
      display: flex;
      min-height: 360px;
      flex-direction: column;
      gap: 12px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 14px;
      border: 1px solid #e7ebf2;
      border-radius: 14px;
      background: var(--panel);
      padding: 16px;
      box-shadow: 0 5px 14px rgba(25, 39, 67, 0.07);
      cursor: grab;
      line-height: 1.45;
      overflow-wrap: anywhere;
      transition: box-shadow 0.2s ease, transform 0.2s ease, opacity 0.2s ease;
    }

    .card:hover {
      box-shadow: 0 9px 20px rgba(25, 39, 67, 0.12);
      transform: translateY(-2px);
    }

    .card.dragging {
      opacity: 0.45;
      cursor: grabbing;
    }

    .card-title {
      flex: 1;
      font-weight: 600;
    }

    .card-del {
      flex: 0 0 auto;
      border: 0;
      border-radius: 8px;
      background: transparent;
      color: #9aa3b2;
      cursor: pointer;
      font-size: 1.15rem;
      line-height: 1;
      padding: 3px 5px;
    }

    .card-del:hover {
      background: #fff0f0;
      color: #dc2626;
    }

    @media (max-width: 800px) {
      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .composer {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 220px;
      }

      .card-list {
        min-height: 120px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <div class="topbar">
      <div>
        <p class="eyebrow">Workspace</p>
        <h1>Kanban board</h1>
      </div>

      <form class="composer" id="card-form">
        <input
          id="new-card"
          type="text"
          autocomplete="off"
          placeholder="Add a task..."
          aria-label="New card title"
        >
        <button id="add-card" type="submit">Add card</button>
      </form>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="To Do card count">0</span>
        </header>
        <div class="card-list" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="Doing card count">0</span>
        </header>
        <div class="card-list" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="Done card count">0</span>
        </header>
        <div class="card-list" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const STORAGE_KEY = "kanban-board-state";
      const columns = [...document.querySelectorAll(".column")];
      const input = document.getElementById("new-card");
      const form = document.getElementById("card-form");

      function createId() {
        if (window.crypto && typeof window.crypto.randomUUID === "function") {
          return window.crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2);
      }

      function getList(column) {
        return column.querySelector(".card-list");
      }

      function updateCounts() {
        columns.forEach(column => {
          column.querySelector(".count").textContent = getList(column).children.length;
        });
      }

      function saveBoard() {
        const state = {};
        columns.forEach(column => {
          state[column.dataset.column] = [...getList(column).querySelectorAll(".card")]
            .map(card => ({
              id: card.dataset.id,
              title: card.querySelector(".card-title").textContent
            }));
        });
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        updateCounts();
      }

      function addCardElement(title, id = createId(), columnName = "todo") {
        const card = document.createElement("article");
        card.className = "card";
        card.draggable = true;
        card.dataset.id = id;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete card");
        deleteButton.textContent = "×";

        deleteButton.addEventListener("click", event => {
          event.stopPropagation();
          card.remove();
          saveBoard();
        });

        card.addEventListener("dragstart", event => {
          card.classList.add("dragging");
          event.dataTransfer.setData("text/plain", card.dataset.id);
          event.dataTransfer.effectAllowed = "move";
        });

        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          columns.forEach(column => column.classList.remove("drag-over"));
        });

        card.append(titleElement, deleteButton);

        const targetColumn = document.querySelector(
          `.column[data-column="${CSS.escape(columnName)}"]`
        ) || document.getElementById("col-todo");

        getList(targetColumn).appendChild(card);
      }

      function loadBoard() {
        let saved = null;
        try {
          saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
        } catch (error) {
          saved = null;
        }

        if (!saved || typeof saved !== "object") {
          updateCounts();
          return;
        }

        ["todo", "doing", "done"].forEach(columnName => {
          if (!Array.isArray(saved[columnName])) return;
          saved[columnName].forEach(item => {
            if (item && typeof item.title === "string") {
              addCardElement(item.title, item.id || createId(), columnName);
            }
          });
        });

        updateCounts();
      }

      form.addEventListener("submit", event => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) return;

        addCardElement(title);
        input.value = "";
        input.focus();
        saveBoard();
      });

      columns.forEach(column => {
        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          column.classList.remove("drag-over");

          const cardId = event.dataTransfer.getData("text/plain");
          const card = document.querySelector(`.card[data-id="${CSS.escape(cardId)}"]`);
          if (!card) return;

          getList(column).appendChild(card);
          saveBoard();
        });
      });

      loadBoard();
    })();
  </script>
</body>
</html>
